public class TypeFactory_constructSpecializedType_TriageGen1Test {

    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
    }



























    @Test
    public void testGenericSubclassWithBindings() {
        // Testing the path where typeParamCount > 0 and not a shortcut
        // We use a class that is a subtype of Map but not in the shortcut list
        // Since there aren't many standard ones, we rely on the fact that the logic 
        // handles the refinement.

        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, String.class);
        // HashMap is in the shortcut list. Let's assume we want to test the complex path.
        // If we use a subclass that isn't in the hardcoded list:
        class CustomMap extends HashMap<String, String> {}

        JavaType result = typeFactory.constructSpecializedType(baseType, CustomMap.class);
        assertEquals(CustomMap.class, result.getRawClass());
        assertEquals(String.class, result.getKeyType().getRawClass());
        assertEquals(String.class, result.getContentType().getRawClass());
    }
